html, body {
  width: 100%; height: 100%;
  background: #0a0a0a;
  color: #fff;
  font-family: 'Share Tech Mono', monospace;
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
}
body {
  display: flex;
  align-items: center;
  justify-content: center;
}

html, body {
  width: 100%;
  height: 100%;
  height: 100dvh;
  min-height: 100vh;
  min-height: 100dvh;
  background: #0a0a0a;
  color: #fff;
  font-family: 'Share Tech Mono', monospace;
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
  overscroll-behavior: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}
body {
  display: flex;
  align-items: center;
  justify-content: center;
  /* No body safe-area padding — that shrank #gameContainer and left a ~40px top dead zone */
}
/* Fullscreen: FS root fills its box; 16:9 stage is 99% and centered (fixes uneven letterbox until resize) */
:fullscreen, :-webkit-full-screen {
  background: #0a0a0a !important;
  width: 100% !important;
  height: 100% !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}
/* When #gameContainer itself is the fullscreen element — size from FS box (100%), then 99% 16:9 */
#gameContainer:fullscreen,
#gameContainer:-webkit-full-screen {
  width: auto !important;
  height: auto !important;
  max-width: min(1280px, 99%) !important;
  max-height: 99% !important;
  aspect-ratio: 16 / 9;
  margin: auto;
  box-shadow: none;
  background: #0a0a0a;
}
/* When document/body is fullscreen — prefer % of FS box over vw/dvh (stale until manual resize) */
:fullscreen #gameContainer,
:-webkit-full-screen #gameContainer {
  width: auto;
  height: auto;
  max-width: min(1280px, 99%);
  max-height: 99%;
  aspect-ratio: 16 / 9;
}
/* Non-blocking Add to Home Screen hint (below portrait overlay z-index) */
#a2hsHint {
  display: none;
  position: fixed;
  left: 50%;
  bottom: calc(12px + env(safe-area-inset-bottom, 0px));
  transform: translateX(-50%);
  z-index: 9000;
  max-width: min(520px, calc(100vw - 24px));
  pointer-events: none;
}
#a2hsHint.show { display: block; pointer-events: auto; }
#a2hsHint .a2hs-inner {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  background: rgba(10,10,10,0.92);
  border: 1px solid rgba(255,45,120,0.45);
  box-shadow: 0 0 24px rgba(255,45,120,0.25);
  color: rgba(255,255,255,0.85);
  font-family: 'Share Tech Mono', monospace;
  font-size: clamp(10px, 2.4vw, 13px);
  letter-spacing: 0.04em;
  line-height: 1.45;
  padding: 10px 12px 10px 14px;
  border-radius: 4px;
}
#a2hsHint .a2hs-inner span { flex: 1; }
#a2hsDismiss {
  flex: none;
  background: transparent;
  border: 1px solid rgba(255,255,255,0.25);
  color: rgba(255,255,255,0.7);
  font-size: 14px;
  line-height: 1;
  padding: 4px 8px;
  cursor: pointer;
  font-family: inherit;
}
#fsToggleBtn {
  display: none;
  position: absolute;
  top: calc(8px + env(safe-area-inset-top, 0px));
  right: calc(8px + env(safe-area-inset-right, 0px));
  z-index: 12;
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.08em;
  color: rgba(255,255,255,0.55);
  background: rgba(0,0,0,0.45);
  border: 1px solid rgba(255,45,120,0.35);
  padding: 6px 10px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
#fsToggleBtn.show { display: block; }
@media (orientation: portrait) and (hover: none) and (pointer: coarse) {
  #a2hsHint.show { display: none !important; }
}

#gameContainer {
  position: relative;
  --gw: min(1280px, 100vw, calc(100vh * 16 / 9));
  width: var(--gw);
  height: calc(var(--gw) * 9 / 16);
  box-shadow: 0 0 60px rgba(0,0,0,0.8), 0 0 120px rgba(0,0,0,0.5);
}

/* Fit 16:9 to viewport, then scale back 1% so chrome/edges don't clip */
#gameContainer {
  position: relative;
  --gw: min(1280px, calc(100vw * 0.99), calc(100dvh * 0.99 * 16 / 9));
  width: var(--gw);
  height: calc(var(--gw) * 9 / 16);
  max-width: 99vw;
  max-height: 99dvh;
  box-shadow: 0 0 60px rgba(0,0,0,0.8), 0 0 120px rgba(0,0,0,0.5);
}

#touchControls {
  position: absolute; bottom: 40px; left: 0; width: 100%; height: 165px; z-index: 8; pointer-events: none; display: none;
}

#touchControls {
  position: absolute;
  bottom: calc(24px + env(safe-area-inset-bottom, 0px));
  left: 0;
  width: 100%;
  height: 165px;
  z-index: 8;
  pointer-events: none;
  display: none;
  padding-left: env(safe-area-inset-left, 0px);
  padding-right: env(safe-area-inset-right, 0px);
}
